#include <iostream>

// Returns the notional actually sendable, capped at the desk limit.
double clippedNotional(double price, int qty, double cap) {
    double notional = price * qty;
    return notional > cap ? cap : notional;   // ternary: condition ? a : b
}

int main() {
    std::cout << clippedNotional(42.17, 250, 9000.0) << '\n';  // capped
    std::cout << clippedNotional(42.17, 100, 9000.0) << '\n';  // under cap
    return 0;
}

