independentExercise.solution:
Output (five lines): `BUY`, `SELL`, `REJECT`, `SELL`, `BUY`.
```cpp
#include <iostream>

void route(char side) {
    switch (side) {
        case 'B':
        case 'b':
            std::cout << "BUY\n";
            break;
        case 'S':
        case 's':
            std::cout << "SELL\n";
            break;
        default:
            std::cout << "REJECT\n";
    }
}

void route(int signedQty) {
    if (signedQty > 0)      std::cout << "BUY\n";
    else if (signedQty < 0) std::cout << "SELL\n";
    else                    std::cout << "REJECT\n";
}

int main() {
    route('b');    // BUY
    route('S');    // SELL
    route(0);      // REJECT
    route(-150);   // SELL
    route(75);     // BUY
    return 0;
}
```
The two overloads are distinguished by parameter type (char vs int); the switch uses deliberate fallthrough to merge the upper/lower-case cases.

